#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# gtt-web-scraper setup wizard (ticket #2): the one-time steps only Garrett can
# do. Run it from this Mac, in a real terminal:
#
#   scripts/setup/wizard.sh
#
# Where things go:
#   - Runtime keys (Firecrawl, TinyFish, Exa, Tavily, dispatch token) go ONLY
#     into the untracked env file on pi5 (PI5_ENV_PATH). The wizard pulls that
#     file into a private temp dir, edits it there, pushes it back over SSH, and
#     deletes the temp copy on exit. No key is ever written into the repo.
#   - Repo secrets CLAUDE_CODE_OAUTH_TOKEN and TS_AUTHKEY go to GitHub via gh.
#   - Non-secret answers (ssh users, port, env path) go to .env.setup in the
#     repo root, which .gitignore already ignores (.env.*), so re-runs remember
#     them.
#
# Safe to re-run: every value already saved is offered back (Enter keeps it),
# every stage re-checks itself, and secrets already on GitHub are only
# replaced if you say so.

REPO="GTalksTech/gtt-web-scraper"
export GH_REPO="$REPO"   # gh secret/api target this repo whatever the remote alias
WIZ_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SETUP_FILE="${SETUP_FILE:-$(cd "$WIZ_DIR/../.." && pwd)/.env.setup}"
WORK="$(mktemp -d)"                  # private (0700): holds the pi5 env copy
trap 'rm -rf "$WORK"' EXIT
PI5_ENV_LOCAL="$WORK/pi5.env"
SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=15 -o StrictHostKeyChecking=accept-new)
LAST_WHY=""

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# wait_enter "msg": like pause, but stops the wizard at end of input instead of
# looping forever.
wait_enter() {
  printf '  %s%s%s ' "$DIM" "$1" "$RESET"
  read -r _ || { printf '\n'; exit 1; }
}

# gate "question": blocks until the human answers yes. Stops at end of input.
gate() {
  local reply
  while true; do
    printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
    read -r reply || { printf '\n'; exit 1; }
    [[ "$reply" =~ ^[Yy] ]] && return 0
    note "No rush. Finish that step, then answer y."
  done
}

# verify "what" cmd...: re-runs a check until it passes; the human fixes things
# in between. This is what makes every stage check itself before moving on.
verify() {
  local what="$1"; shift
  until "$@"; do
    warn "not yet: $what${LAST_WHY:+ ($LAST_WHY)}"
    LAST_WHY=""
    wait_enter "Fix it, then press Enter to check again (Ctrl-C stops; re-running resumes)."
  done
  LAST_WHY=""
  ok "$what"
}

has() { command -v "$1" >/dev/null 2>&1; }

# ── local answers (.env.setup) and pi5's env file ─────────────────────────
use_setup_file() { ENV_FILE="$SETUP_FILE"; }
use_pi5_env()    { ENV_FILE="$PI5_ENV_LOCAL"; }

# ask_default KEY "Prompt" DEFAULT: ask, falling back to DEFAULT on Enter.
ask_default() {
  local key="$1" prompt="$2" default="$3"
  if _existing "$key" >/dev/null; then ask "$key" "$prompt"
  else ask "$key" "$prompt [$default]"; fi
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
}

pull_pi5_env() {
  (umask 077 && : > "$PI5_ENV_LOCAL")
  # No file yet is fine; a file we can't read must fail, or the next push
  # would replace it with only the keys entered this run.
  ssh "${SSH_OPTS[@]}" "$PI5_SSH_USER@$PI5_HOST" \
    "if [ -e $PI5_ENV_PATH ]; then cat $PI5_ENV_PATH; fi" > "$PI5_ENV_LOCAL"
}

# PI5_ENV_PATH is checked against a safe pattern in stage 1, so it can go into
# the remote command unquoted (which lets ~ expand on pi5).
push_pi5_env() {
  ssh "${SSH_OPTS[@]}" "$PI5_SSH_USER@$PI5_HOST" \
    "umask 077 && mkdir -p \$(dirname $PI5_ENV_PATH) && cat > $PI5_ENV_PATH.tmp && mv $PI5_ENV_PATH.tmp $PI5_ENV_PATH" \
    < "$PI5_ENV_LOCAL"
}

save_setting() { use_setup_file; write_env "$1" "$2"; }

save_pi5() {
  use_pi5_env
  write_env "$1" "$2"
  verify "saved $1 in pi5:$PI5_ENV_PATH" push_pi5_env
}

# ── checks ─────────────────────────────────────────────────────────────────
# http_code METHOD URL HEADERS [JSON]: prints the HTTP status (000 = no answer).
# Headers carry the key, so they go in through a file descriptor rather than
# the command line, keeping the key out of `ps`.
http_code() {
  local method="$1" url="$2" headers="$3" body="${4:-}" code=""
  if [[ -n "$body" ]]; then
    code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 30 -X "$method" \
      -H @<(printf '%s\n' "$headers") -H 'Content-Type: application/json' \
      --data "$body" "$url" 2>/dev/null) || true
  else
    code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 30 -X "$method" \
      -H @<(printf '%s\n' "$headers") "$url" 2>/dev/null) || true
  fi
  printf '%s' "${code:-000}"
}

expect_http() { # WANT METHOD URL HEADERS [JSON]
  local want="$1" code; shift
  code=$(http_code "$@")
  LAST_WHY="HTTP $code"
  [[ "$code" == "$want" ]]
}

# Each check costs nothing or next to nothing: Firecrawl and Tavily have usage
# endpoints, TinyFish search is free, Exa runs one 1-result search.
check_firecrawl() { expect_http 200 GET https://api.firecrawl.dev/v2/team/credit-usage "Authorization: Bearer $1"; }
check_tinyfish()  { expect_http 200 GET 'https://api.search.tinyfish.ai?query=raspberry+pi+5' "X-API-Key: $1"; }
check_exa()       { expect_http 200 POST https://api.exa.ai/search "x-api-key: $1" '{"query":"raspberry pi 5","numResults":1}'; }
check_tavily()    { expect_http 200 GET https://api.tavily.com/usage "Authorization: Bearer $1"; }

# The dispatch check sends one real repository dispatch event of type
# setup-wizard-check. No workflow listens for that type, so it does nothing,
# but a 204 proves the token can do the one job it exists for.
check_dispatch() {
  if [[ "$1" != github_pat_* ]]; then
    LAST_WHY="not a fine-grained token: it should start with github_pat_"; return 1
  fi
  expect_http 204 POST "https://api.github.com/repos/$REPO/dispatches" \
    "Authorization: Bearer $1"$'\n'"Accept: application/vnd.github+json"$'\n'"X-GitHub-Api-Version: 2022-11-28" \
    '{"event_type":"setup-wizard-check"}'
}

# The token goes in through a subshell's environment, not the command line,
# so it stays out of `ps`. Empty is refused: claude would fall back to this
# Mac's own login and pass.
check_claude() {
  [[ -n "$1" ]] || { LAST_WHY="nothing pasted"; return 1; }
  LAST_WHY="Claude didn't answer using that token"
  ( unset ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN
    export CLAUDE_CODE_OAUTH_TOKEN="$1"
    claude -p "Reply with the single word: ok" 2>/dev/null ) | grep -qiE '^ *ok[.!]? *$'
}

check_ts_authkey() {
  LAST_WHY="Tailscale auth keys start with tskey-auth-"
  [[ "$1" == tskey-auth-* ]]
}

# capture_key KEY "Prompt" CHECK: hidden entry until CHECK accepts the value,
# then saves it into pi5's env file. Enter keeps the value already on pi5.
capture_key() {
  local key="$1" prompt="$2" check="$3"
  use_pi5_env
  while true; do
    ask_secret "$key" "$prompt"
    if [[ -z "${!key}" ]]; then warn "nothing pasted"; continue; fi
    say "checking it..."
    if "$check" "${!key}"; then ok "$key works"; break; fi
    warn "that didn't work ($LAST_WHY). Copy it again and paste it."
  done
  if [[ "${!key}" == "$(_existing "$key" || true)" ]]; then
    ok "$key already saved on pi5"
  else
    save_pi5 "$key" "${!key}"
  fi
}

secret_exists() {
  gh secret list --json name --jq '.[].name' 2>/dev/null | grep -qx "$1"
}

# put_secret NAME VALUE: set the repo secret, then confirm GitHub lists it.
put_secret() {
  local name="$1" value="$2" s kept=()
  while true; do
    set_secret "$name" "$value"
    if secret_exists "$name"; then break; fi
    wait_enter "gh couldn't set $name. Check 'gh auth status', then press Enter to retry."
  done
  # A retry that worked shouldn't leave a stale "do it by hand" line behind.
  if (( ${#SKIPPED[@]} )); then
    for s in "${SKIPPED[@]}"; do [[ "$s" == *" $name "* ]] || kept+=("$s"); done
    SKIPPED=(); (( ${#kept[@]} )) && SKIPPED=("${kept[@]}")
  fi
  ok "GitHub lists secret $name"
}

# keep_secret NAME: on re-runs, true when the human wants to keep a secret
# that's already on GitHub (they can't be read back, so we ask).
keep_secret() {
  secret_exists "$1" || return 1
  say "Repo secret $1 is already set."
  if confirm "Replace it with a new one?"; then return 1; fi
  ok "kept the existing $1"
  return 0
}

# ── tailnet lookups ────────────────────────────────────────────────────────
ts_json() { tailscale status --json 2>/dev/null; }
ts_running() { ts_json | jq -e '.BackendState == "Running"' >/dev/null; }
# ts_peer HOST JQ-EXPR: a field of the peer whose name is HOST.
ts_peer() {
  ts_json | jq -r --arg h "$1" \
    "[.Peer[] | select((.HostName | ascii_downcase) == (\$h | ascii_downcase))][0] | $2 // empty"
}
peer_ip()   { ts_peer "$1" '.TailscaleIPs[0]'; }
peer_seen() { LAST_WHY="no device named $1 on your tailnet"; [[ -n "$(peer_ip "$1")" ]]; }
ts_ssh_on() {
  LAST_WHY="Tailscale doesn't advertise SSH on $1 yet"
  [[ "$(ts_peer "$1" '(.sshHostKeys // []) | length')" -gt 0 ]]
}
ssh_login() { LAST_WHY="ssh $1@$2 failed"; ssh "${SSH_OPTS[@]}" "$1@$2" true </dev/null; }

gh_admin() {
  LAST_WHY="gh's active account can't administer $REPO (try: gh auth switch -u GTalksTech)"
  [[ "$(gh api "repos/$REPO" --jq .permissions.admin 2>/dev/null)" == "true" ]]
}

safe_path() {
  LAST_WHY="use letters, digits, ~ / . _ - only (no spaces)"
  [[ "$1" =~ ^[~A-Za-z0-9._/-]+$ && "$1" == *[!/] ]]
}

# policy_snippet: the Tailscale policy additions, filled in from the tailnet.
policy_snippet() {
  local pi5_dst hermes_dst
  pi5_dst=$(ts_peer "$PI5_HOST" '(.Tags // [])[0]'); pi5_dst="${pi5_dst:-autogroup:self}"
  hermes_dst=$(ts_peer "$HERMES_HOST" '(.Tags // [])[0]'); hermes_dst="${hermes_dst:-autogroup:self}"
  cat <<EOF
// ── gtt-web-scraper (from scripts/setup/wizard.sh) ──
// Merge each block into the section of the same name in your policy file.
"hosts": {
  "gtt-mac":     "$TS_MAC_IP",   // this Mac
  "gtt-desktop": "$TS_DESKTOP_IP",   // $DESKTOP_HOST
  "gtt-pi5":     "$TS_PI5_IP",
  "gtt-hermes":  "$TS_HERMES_IP",
},
"tagOwners": {
  "tag:ci": ["$TS_LOGIN"],
},
"grants": [
  // GitHub Actions runners (ephemeral, tag:ci) reach ONLY the scraper's port on pi5.
  {"src": ["tag:ci"], "dst": ["gtt-pi5"], "ip": ["tcp:$SERVICE_PORT"]},
  // SSH (port 22) to pi5 and hermes ONLY from your two computers.
  {"src": ["gtt-mac", "gtt-desktop"], "dst": ["gtt-pi5", "gtt-hermes"], "ip": ["tcp:22"]},
],
"ssh": [
  {"action": "accept", "src": ["$TS_LOGIN"], "dst": ["$pi5_dst"], "users": ["$PI5_SSH_USER"]},
  {"action": "accept", "src": ["$TS_LOGIN"], "dst": ["$hermes_dst"], "users": ["$HERMES_SSH_USER"]},
],
EOF
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10

banner "gtt-web-scraper: one-time setup (about 30 minutes)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check this Mac's tools and learn the tailnet"
say "First, a quick check that this Mac has what the later stages need."
verify "gh installed"        has gh
verify "ssh installed"       has ssh
verify "curl installed"      has curl
verify "jq installed (brew install jq)" has jq
verify "claude installed"    has claude
verify "tailscale CLI installed" has tailscale
verify "Tailscale is connected on this Mac" ts_running
verify "gh can manage $REPO's secrets" gh_admin

use_setup_file
PI5_HOST=pi5; HERMES_HOST=hermes
verify "found $PI5_HOST on the tailnet"    peer_seen "$PI5_HOST"
verify "found $HERMES_HOST on the tailnet" peer_seen "$HERMES_HOST"
while true; do
  ask_default DESKTOP_HOST "Tailscale name of your desktop PC?" "GM-DESKTOP"
  peer_seen "$DESKTOP_HOST" && break
  warn "$LAST_WHY"
done
ok "found $DESKTOP_HOST on the tailnet"
save_setting DESKTOP_HOST "$DESKTOP_HOST"
ask PI5_SSH_USER "Your login username on pi5?"
save_setting PI5_SSH_USER "$PI5_SSH_USER"
ask HERMES_SSH_USER "Your login username on hermes?"
save_setting HERMES_SSH_USER "$HERMES_SSH_USER"
ask_default SERVICE_PORT "Port the scraper will listen on, on pi5?" "3002"
save_setting SERVICE_PORT "$SERVICE_PORT"
while true; do
  ask_default PI5_ENV_PATH "Path of the scraper's env file on pi5?" "~/gtt-web-scraper/.env"
  safe_path "$PI5_ENV_PATH" && break
  warn "$LAST_WHY"
done
save_setting PI5_ENV_PATH "$PI5_ENV_PATH"

TS_LOGIN=$(ts_json | jq -r '.User[(.Self.UserID | tostring)].LoginName // empty')
TS_MAC_IP=$(ts_json | jq -r '.Self.TailscaleIPs[0]')
TS_DESKTOP_IP=$(peer_ip "$DESKTOP_HOST")
TS_PI5_IP=$(peer_ip "$PI5_HOST")
TS_HERMES_IP=$(peer_ip "$HERMES_HOST")
wait_enter "All set. Press Enter for the Tailscale policy."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Tailscale policy: CI tag, port rules, SSH rules"
say "This adds a tag:ci for GitHub's runners, opens only the scraper's port to"
say "it, and limits SSH on pi5 and hermes to this Mac and $DESKTOP_HOST."
policy_snippet > "$WORK/policy.hujson"
printf '\n'; sed 's/^/    /' "$WORK/policy.hujson"; printf '\n'
if has pbcopy; then pbcopy < "$WORK/policy.hujson"; note "(copied to your clipboard)"; fi
open_url "https://login.tailscale.com/admin/acls/file"
step "Merge each block above into the section of the same name (create it if missing)."
step "If the editor shows a different login than $TS_LOGIN, use what it shows."
step "Look for a broad rule like {\"src\": [\"*\"], \"dst\": [\"*\"], \"ip\": [\"*\"]}"
step "(or the old acls form, src \"*\" to dst \"*:*\"). It lets every device, tag:ci"
step "included, reach every port, which defeats both limits above. Replace it with:"
say  "    {\"src\": [\"autogroup:member\"], \"dst\": [\"*\"],"
say  "     \"ip\": [\"tcp:1-21\", \"tcp:23-65535\", \"udp:*\", \"icmp:*\"]},"
note "That keeps your own devices reaching everything except port 22. Tagged devices"
note "(pi5 is tag:pi) stop starting connections to others; add a grant if pi5 needs one."
note "SSH to any other machine then needs its own tcp:22 grant, like the one above."
step "Click Save. Tailscale checks the syntax and refuses a broken file."
gate "Saved, and nothing else opens port 22 on pi5 or hermes to other devices?"
ok "Tailscale policy updated"
wait_enter "Press Enter for Tailscale SSH."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Turn on Tailscale SSH on pi5 and hermes"
say "On each machine, at its own keyboard or in any session you already have:"
step "pi5:    sudo tailscale set --ssh"
step "hermes: sudo tailscale set --ssh"
note "If it warns you'll lose your current SSH session, that's expected: re-run it"
note "with --accept-risk=lose-ssh, then reconnect."
wait_enter "Press Enter once both are done."
verify "Tailscale SSH is on for $PI5_HOST"    ts_ssh_on "$PI5_HOST"
verify "Tailscale SSH is on for $HERMES_HOST" ts_ssh_on "$HERMES_HOST"
verify "SSH login from this Mac to $PI5_HOST"    ssh_login "$PI5_SSH_USER" "$PI5_HOST"
verify "SSH login from this Mac to $HERMES_HOST" ssh_login "$HERMES_SSH_USER" "$HERMES_HOST"
verify "read pi5:$PI5_ENV_PATH (or found none yet)" pull_pi5_env
wait_enter "Press Enter for the API keys."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Firecrawl key (the Paid Fetcher, the key you already have)"
say "Same key Hermes uses today. It's the scraper's last resort, never search."
open_url "https://www.firecrawl.dev/app/api-keys"
step "Copy your API key (starts with fc-)."
capture_key FIRECRAWL_API_KEY "Paste the Firecrawl key:" check_firecrawl
wait_enter "Press Enter for TinyFish."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "TinyFish key (Search Provider 1, free)"
open_url "https://agent.tinyfish.ai/api-keys"
step "Sign up or sign in (free), then click 'Create API Key'."
step "Copy the key now: TinyFish shows it only once."
capture_key TINYFISH_API_KEY "Paste the TinyFish key:" check_tinyfish
wait_enter "Press Enter for Exa."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Exa key (Search Provider 2, free monthly credit)"
open_url "https://dashboard.exa.ai/api-keys"
step "Sign up or sign in (free), create an API key, and copy it."
note "The check runs one 1-result search: a fraction of a cent of free credit."
capture_key EXA_API_KEY "Paste the Exa key:" check_exa
wait_enter "Press Enter for Tavily."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Tavily key (Search Provider 3, 1,000 free credits a month)"
open_url "https://app.tavily.com"
step "Sign up or sign in (free). Copy the API key on the overview page (starts with tvly-)."
capture_key TAVILY_API_KEY "Paste the Tavily key:" check_tavily
wait_enter "Press Enter for the GitHub dispatch token."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub token that lets pi5 report Incidents"
say "pi5 files Incidents by sending repository dispatch events to $REPO."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Make sure you're signed in as GTalksTech (avatar, top right)."
step "Token name: gtt-web-scraper pi5 dispatch. Expiration: the longest offered."
step "Resource owner: GTalksTech. Repository access: Only select repositories → gtt-web-scraper."
step "Permissions → Repository permissions → Contents: Read and write. Nothing else."
note "Contents: write is the narrowest permission GitHub accepts for dispatch events."
note "It could also push code, so this token lives only on pi5, never in the repo."
step "Generate token, then copy it (starts with github_pat_)."
note "The check sends one harmless 'setup-wizard-check' event that no workflow handles."
capture_key GITHUB_DISPATCH_TOKEN "Paste the token:" check_dispatch
wait_enter "Press Enter for the Claude token."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Claude subscription token for the fixing agent (repo secret)"
if ! keep_secret CLAUDE_CODE_OAUTH_TOKEN; then
  say "This lets Claude Code in GitHub Actions run on your Max plan. The token lasts a year."
  wait_enter "Press Enter to run 'claude setup-token'. Approve it in the browser it opens."
  claude setup-token || warn "claude setup-token exited with an error; paste the token if it printed one"
  step "Copy the long token it printed (above)."
  while true; do
    ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token:"
    say "checking it with one short Claude call..."
    check_claude "$CLAUDE_CODE_OAUTH_TOKEN" && break
    warn "that didn't work ($LAST_WHY). Copy it again, or re-run 'claude setup-token' in another tab."
  done
  ok "the token works"
  put_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
  _clear   # the token was printed on screen; wipe it from the scrollback
  ok "CLAUDE_CODE_OAUTH_TOKEN saved and cleared from the screen"
fi
wait_enter "Press Enter for the last step, the Tailscale CI key."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Tailscale auth key for CI (repo secret)"
if ! keep_secret TS_AUTHKEY; then
  say "GitHub's every-2-hours reachability check joins the tailnet with this key."
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Click 'Generate auth key'. Description: gtt-web-scraper CI."
  step "Reusable: ON (the check runs every 2 hours). Expiration: 90 days (the maximum)."
  step "Ephemeral: ON. Pre-approved: ON. Tags: ON, then pick tag:ci."
  step "Generate key, then copy it (starts with tskey-auth-)."
  note "It expires in 90 days; the reachability check will raise an Incident when it does."
  while true; do
    ask_secret TS_AUTHKEY "Paste the auth key:"
    check_ts_authkey "$TS_AUTHKEY" && break
    warn "that doesn't look right ($LAST_WHY). Copy it again."
  done
  put_secret TS_AUTHKEY "$TS_AUTHKEY"
fi
wait_enter "Press Enter for the summary."

ENV_FILE="pi5:$PI5_ENV_PATH and $SETUP_FILE"
finish
say "Every later ticket can now be done by agents over Tailscale SSH."
note "Re-run this wizard any time; Enter keeps what's saved."
printf '\n'
}

run_wizard "$@"; exit
